import{_ as r,C as t,o as i,c as d,j as o,a as l,E as a,a6 as c}from"./chunks/framework.CD0vXS2f.js";const S=JSON.parse('{"title":"04 · Cohesive Stateful AI Stamp Failover (Cosmos DB & AI Search)","description":"Synchronizing multi-turn agent state, workpaper lineage, and grounded knowledge indexes across paired Azure regions so model failover translates into end-to-end application continuity.","frontmatter":{"title":"04 · Cohesive Stateful AI Stamp Failover (Cosmos DB & AI Search)","description":"Synchronizing multi-turn agent state, workpaper lineage, and grounded knowledge indexes across paired Azure regions so model failover translates into end-to-end application continuity."},"headers":[],"relativePath":"playbooks/multi-region-bcp/04-stateful-stamp-failover.md","filePath":"playbooks/multi-region-bcp/04-stateful-stamp-failover.md","lastUpdated":1795642852816,"verifiedStamp":"2026-11-25 13:40 PST"}'),p={name:"playbooks/multi-region-bcp/04-stateful-stamp-failover.md"};function g(m,e,h,u,y,f){const n=t("PlaybookMeta"),s=t("PageBrief");return i(),d("div",null,[e[0]||(e[0]=o("h1",{id:"_04-·-cohesive-stateful-ai-stamp-failover-cosmos-db-ai-search",tabindex:"-1"},[l("04 · Cohesive Stateful AI Stamp Failover (Cosmos DB & AI Search) "),o("a",{class:"header-anchor",href:"#_04-·-cohesive-stateful-ai-stamp-failover-cosmos-db-ai-search","aria-label":'Permalink to "04 · Cohesive Stateful AI Stamp Failover (Cosmos DB & AI Search)"'},"​")],-1)),a(n,{track:"03 · Multi-Region Foundry BCP, Residency & Failover Drills",verified:"2026-11-19 22:12 PST",status:"Live v2.0"}),a(s,{stage:"design",readTime:"4 min read",problem:"Azure AI Search does not natively replicate indexes across regions; failing over APIM + Foundry while leaving search or session checkpoints in Region A breaks every RAG-grounded agent turn.",takeaway:"Treat ADLS Gen2 (GZRS/RA-GZRS) as the single source of document truth, run independent AI Search stamps per region fed from that storage, and use Cosmos DB multi-region failover for session checkpoints.",csaUse:"Review the 4-component stamp matrix below to verify zero single-region stateful anchors remain in your agent architecture."}),e[1]||(e[1]=c('<h2 id="end-to-end-ai-stamp-dependency-matrix" tabindex="-1">End-to-End AI Stamp Dependency Matrix <a class="header-anchor" href="#end-to-end-ai-stamp-dependency-matrix" aria-label="Permalink to &quot;End-to-End AI Stamp Dependency Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Stamp Layer</th><th style="text-align:left;">Primary Region Configuration</th><th style="text-align:left;">Secondary Region Configuration</th><th style="text-align:left;">Failover Mechanism &amp; RPO/RTO</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. Edge &amp; AI Gateway (<code>APIM</code> / <code>Front Door</code>)</strong></td><td style="text-align:left;">APIM Premium multi-region unit (or regional Standard v2 behind Azure Front Door / Traffic Manager) <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Secondary APIM unit in paired region with identical backend pool &amp; Managed Identity RBAC.</td><td style="text-align:left;">Automatic health-probe routing (<code>&lt;15–30s</code> RTO; <code>0</code> state loss).</td></tr><tr><td style="text-align:left;"><strong>2. Model Inference (<code>Microsoft Foundry</code>)</strong></td><td style="text-align:left;">Primary <code>PTU-M</code> + local <code>Standard</code> spillover pinned to explicit snapshot (<code>e.g., 2026-09-29</code>).</td><td style="text-align:left;">Secondary <code>DataZoneStandard</code> / <code>Regional</code> deployment pinned to <strong>identical model snapshot</strong> and system prompt version.</td><td style="text-align:left;">APIM backend-pool circuit breaker (<code>&lt;15s</code> RTO; cold KV cache warms in <code>5–15m</code>).</td></tr><tr><td style="text-align:left;"><strong>3. Session State &amp; Lineage (<code>Azure Cosmos DB</code>)</strong></td><td style="text-align:left;">Zone-redundant (<code>ZRS</code>) NoSQL container storing <code>thread_id</code> append-only history, tool outputs, and workpaper hashes <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Multi-region replica (<code>Session</code> consistency; service-managed failover or multi-region writes) <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Cosmos SDK <code>PreferredLocations</code> auto-switches reads/writes (<code>RPO ~0</code> on multi-write / <code>&lt;5m</code> async).</td></tr><tr><td style="text-align:left;"><strong>4. Knowledge Base (<code>ADLS Gen2</code> + <code>Azure AI Search</code>)</strong></td><td style="text-align:left;"><code>RA-GZRS</code> ADLS Gen2 markdown/chunk store + Primary Azure AI Search (<code>Basic+</code> / <code>S1+</code> with ZRS replicas) <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Independent Secondary Azure AI Search service indexing continuously from the same geo-replicated ADLS container <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>.</td><td style="text-align:left;">Agent MCP / search client retries against Secondary Search endpoint (<code>RPO &lt;15m</code> indexer cadence; <code>&lt;5s</code> read switch).</td></tr><tr><td style="text-align:left;"><strong>5. Agent Runtime (<code>ACA</code> / <code>AKS</code>)</strong></td><td style="text-align:left;">Zone-redundant Container Apps + ACA Dynamic Session Pool in Primary Region.</td><td style="text-align:left;">Warm-scaled Container Apps + pre-provisioned Session Pool in Secondary Region.</td><td style="text-align:left;">Front Door / Traffic Manager origin health probe shifts active sessions cleanly.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Why Model 2 Stateless Agents Simplify Regional Cutover</p><p>Because the hub&#39;s <strong>Model 2 Stateless Agent Pattern</strong> (<a href="/enterprise-azure-ai-hub/playbooks/prompt-caching/start/02-stateless-agents">Playbook 01 · Ch 02</a>) persists conversation turns and episodic embeddings in <strong>Cosmos DB</strong> rather than pinning state inside Foundry server-side thread memory or single-node RAM, an active user conversation seamlessly resumes on Turn <code>N+1</code> in Secondary Region B with zero lost messages! For <code>DiskANN</code> + <code>RRF</code> hybrid vector indexing, immutable vector policy cutovers, and OneLake-to-AI-Search Shared Private Link parity (<code>D7</code>, <code>D8</code>, <code>D11</code>), see <a href="/enterprise-azure-ai-hub/playbooks/ai-data-strategy/04-cosmos-vector-hybrid-retrieval">Playbook 05 · Ch 04</a>.</p></div>',3))])}const A=r(p,[["render",g]]);export{S as __pageData,A as default};
